/* Speculative Score Draft for Tone.js */
// Setup: Tempo 120 BPM, Time Signature 4/4. Use a global reverb and delay.

// Rhythm Section:
const kick = new Tone.MembraneSynth({ volume: -6 }).toDestination();
const snare = new Tone.NoiseSynth({ envelope: { decay: 0.15 }, volume: -7 }).toDestination(); // Add a large Convolver reverb.
const hats = new Tone.MetalSynth({ envelope: { decay: 0.08 }, volume: -18 }).toDestination();

// Kick part: new Tone.Loop(time => kick.triggerAttackRelease('C1', '8n', time), '4n').start(0);
// Snare part: new Tone.Sequence((time, note) => { if(note) snare.triggerAttack(time) }, [null, 'x', null, 'x'], '4n').start(0);
// Hats part: new Tone.Loop(time => hats.triggerAttack(time), '16n').start(0);

// Melodic/Harmonic Section:
const bass = new Tone.MonoSynth({ oscillator: { type: 'sawtooth' }, envelope: { attack: 0.01, decay: 0.2, sustain: 0.1, release: 0.1 }, filter: { type: 'lowpass', frequency: 1500 }, volume: -10 }).toDestination();
// Bass Part: new Tone.Sequence((time, note) => bass.triggerAttackRelease(note, '8n', time), ['A1', 'A2', 'A1', 'A2', 'G1', 'G2', 'G1', 'G2'], '8n').start(0);

const lead = new Tone.PolySynth(Tone.Synth, { oscillator: { type: 'fatsawtooth', count: 4, spread: 30 }, envelope: { release: 0.8 }, volume: -12 }).toDestination();
// Lead Part (Chorus): ['A4', null, 'C5', 'G4', null, 'E4', 'D4', null]

const pad = new Tone.PolySynth(Tone.Synth, { oscillator: { type: 'triangle' }, envelope: { attack: 1.2, release: 2.5 }, volume: -22 }).toDestination();
// Pad Part: Plays long chords like ['A3', 'C4', 'E4']
